// ForgeKit stamp - the version-tag ritual, once (Slotto v1.4.0 pattern).
//
// All-projects rule: every web page visibly shows
// "v<version> - updated <date time>". Nine projects carried a copy of the
// tool that does it; this is that tool as a library. Node only (.mjs so
// a CommonJS tools/stamp.js can `import()` it).
//
//   // tools/stamp.js in a consumer:
//   import('../web/vendor/forgekit/stamp.mjs').then(m => m.stamp({
//     root: new URL('..', import.meta.url),      // or path.join(__dirname, '..')
//     globalName: 'CELLFORGE_VERSION',
//   }));
//
// What it does (all optional, defaults fit the common layout):
//   - reads VERSION at root (SemVer)
//   - writes `versionJs` (default web/version.js): window.<globalName> =
//     { version, built } + the snippet that fills every .version-tag
//   - rewrites every ?v=<stamp> in `html` files (default web/index.html)
//     to <version>-<yyyymmddHHMM>
//   - applies extra `rewrites`: [{ file, re, to }] where `to` is a string
//     with {version} {built} {stamp} placeholders or a function(ctx) - for
//     single-file apps that stamp in place (LakeForge) or a server
//     constant that feeds /health
//
// Returns { version, built, stamp, wrote: [...] }.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const p2 = n => String(n).padStart(2, '0');

// Pure: version + date -> the three strings every consumer needs.
export function buildStamp(version, date = new Date()) {
  const built = date.getFullYear() + '-' + p2(date.getMonth() + 1) + '-' + p2(date.getDate()) +
    ' ' + p2(date.getHours()) + ':' + p2(date.getMinutes());
  return { version, built, stamp: version + '-' + built.replace(/[-: ]/g, '') };
}

// Pure: the generated version.js text.
export function versionJsText(globalName, version, built) {
  return `/* GENERATED by ForgeKit stamp - do not edit by hand. */
window.${globalName} = { version: "${version}", built: "${built}" };
(function () {
  var text = "v" + ${globalName}.version + " - updated " + ${globalName}.built;
  var els = document.querySelectorAll(".version-tag");
  for (var i = 0; i < els.length; i++) els[i].textContent = text;
})();
`;
}

export const CACHE_STAMP_RE = /\?v=[A-Za-z0-9.\-]+/g;

function toPath(p) {
  if (p instanceof URL) return fileURLToPath(p);
  if (typeof p === 'string' && p.startsWith('file:')) return fileURLToPath(p);
  return p;
}

function fill(to, ctx) {
  if (typeof to === 'function') return to(ctx);
  return String(to).replace(/\{(version|built|stamp)\}/g, (_, k) => ctx[k]);
}

export function stamp({
  root,
  globalName,
  versionJs = 'web/version.js',
  html = ['web/index.html'],
  rewrites = [],
  date = new Date(),
  log = console.log,
} = {}) {
  if (!root) throw new Error('stamp: root is required');
  root = toPath(root);
  const version = fs.readFileSync(path.join(root, 'VERSION'), 'utf8').trim();
  if (!version) throw new Error('stamp: VERSION is empty');
  const ctx = buildStamp(version, date);
  const wrote = [];

  if (versionJs && globalName) {
    const f = path.join(root, versionJs);
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, versionJsText(globalName, ctx.version, ctx.built));
    wrote.push(versionJs);
    log(`${versionJs}: v${ctx.version} built ${ctx.built}`);
  }

  for (const rel of html || []) {
    const f = path.join(root, rel);
    if (!fs.existsSync(f)) { log(`${rel}: missing, skipped`); continue; }
    const before = fs.readFileSync(f, 'utf8');
    const n = (before.match(CACHE_STAMP_RE) || []).length;
    const after = before.replace(CACHE_STAMP_RE, '?v=' + ctx.stamp);
    if (after !== before) { fs.writeFileSync(f, after); wrote.push(rel); }
    log(`${rel}: ${n} stamp(s) -> ?v=${ctx.stamp}`);
  }

  for (const rw of rewrites) {
    const f = path.join(root, rw.file);
    const before = fs.readFileSync(f, 'utf8');
    if (!rw.re.test(before)) throw new Error(`stamp: ${rw.file}: pattern ${rw.re} not found - refusing`);
    const re = rw.re.global ? rw.re : new RegExp(rw.re.source, rw.re.flags);
    const after = before.replace(re, fill(rw.to, ctx));
    if (after !== before) { fs.writeFileSync(f, after); wrote.push(rw.file); }
    log(`${rw.file}: rewritten (v${ctx.version})`);
  }

  return { ...ctx, wrote };
}

// CLI: node stamp.mjs --root <dir> --global NAME [--version-js web/version.js] [--html web/index.html,...]
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const opt = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
  const html = opt('--html', 'web/index.html').split(',').filter(Boolean);
  stamp({ root: opt('--root', process.cwd()), globalName: opt('--global'), versionJs: opt('--version-js', 'web/version.js'), html });
}
